import {booked} from './payments';
import {paymentReference,isPaymentReference} from './payment-reference';
export {wholeCheckout,reclaimReservation} from './settlement-recovery';
export function splitCheckout(line:string,parts:number[]){
  if ([...booked.keys()].some(reference=>isPaymentReference(reference,line))) return {status:'already-booked'};
  parts.forEach((cents,i)=>booked.set(paymentReference(line,i),cents));
  return {status:'booked'};
}

payment-reference.ts:
/** Canonical storage key for a checkout payment or one of its allocations. */
export function paymentReference(line: string, part?: number): string {
  return part === undefined
    ? `payment:${line}`
    : `payment:${line}:part:${part}`;
}

/** Recognize any key belonging to this checkout line. */
export function isPaymentReference(reference: string, line: string): boolean {
  const base = paymentReference(line);
  return reference === base || reference.startsWith(`${base}:part:`);
}

