import {booked} from './payments';
import {paymentReference,isPaymentReference} from './payment-reference';
export function wholeCheckout(line:string,cents:number){if([...booked.keys()].some(reference=>isPaymentReference(reference,line)))return {status:'already-booked'};booked.set(paymentReference(line),cents);return {status:'booked'};}
export function reclaimReservation(line:string){return ![...booked.keys()].some(reference=>isPaymentReference(reference,line));}
